import sys
import traceback
from urllib.parse import unquote

sys.path.insert(0, "/app")
import server.app as app

def decode(pct):
    return unquote(pct, encoding="utf-8", errors="strict")

odd_key = decode("e1%C2%8E%C2%B6%F3%9C%B8%A0")
nested_odd_key = "docs/" + decode("%F3%9C%B8%A0") + "/readme.txt"
keys = [odd_key] * 10 + [decode("%C2%8E"), decode("%C2%B6"), nested_odd_key]

print("odd_key repr:", repr(odd_key))

for k in keys:
    try:
        path = app.resolve_blob_path("/data", k)
    except app.InvalidKeyError:
        print(repr(k), "structural reject")
        continue
    try:
        app.write_blob_atomic(path, b"x")
        print(repr(k), "write OK")
    except app.InvalidKeyError as e:
        print(repr(k), "write InvalidKeyError, cause=", repr(e.__cause__))

print("--- now plain key ---")
path = app.resolve_blob_path("/data", "greeting.txt")
try:
    app.write_blob_atomic(path, b"hello world")
    print("greeting.txt write OK")
except app.InvalidKeyError as e:
    print("greeting.txt write FAILED, cause=", repr(e.__cause__))
    traceback.print_exception(type(e.__cause__), e.__cause__, e.__cause__.__traceback__)

